/* From Uiverse.io by Na3ar-17  - Tags: simple, icon, animation, button */
.__UIV_SCOPE__ .button {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 18px;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  font-weight: 500;
  background-color: #268bff;
  color: white;
  border: none;
  gap: 2px;
  border-radius: 8px;
  padding: 4px 8px;
}

.__UIV_SCOPE__ .button .icon {
  width: 20px;
}

.__UIV_SCOPE__ .button:hover {
  background-color: #268bffaf;
}
.__UIV_SCOPE__ .button:active {
  transform: translateY(2px);
}
